import{_ as t,o as d,c as o,ag as a}from"./chunks/framework.TQKaXlFR.js";const h=JSON.parse('{"title":"菜单与页面入口","description":"","frontmatter":{},"headers":[],"relativePath":"features/menus.md","filePath":"features/menus.md"}'),r={name:"features/menus.md"};function c(s,e,i,n,l,u){return d(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="菜单与页面入口" tabindex="-1">菜单与页面入口 <a class="header-anchor" href="#菜单与页面入口" aria-label="Permalink to &quot;菜单与页面入口&quot;">​</a></h1><p>菜单管理位于 <strong>系统管理 → 菜单管理</strong>。当前源码默认导航按 <strong>系统管理、通用能力、运行维护、AI管理</strong> 四个一级目录组织。页面的可见集合来自用户实际授权，不保证每个身份都能看到四组中的全部子项。v1.2.0静态旧快照沿用原三组布局，不能据此推断当前源码的菜单结构。</p><h2 id="菜单字段" tabindex="-1">菜单字段 <a class="header-anchor" href="#菜单字段" aria-label="Permalink to &quot;菜单字段&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>含义与填写要求</th></tr></thead><tbody><tr><td><code>menuType</code></td><td><code>M</code> 目录、<code>C</code> 页面、<code>F</code> 动作；按页面选项填写</td></tr><tr><td><code>parentId</code> / <code>orderNum</code></td><td>父级与同级排序；父级 ID 保持字符串精度</td></tr><tr><td><code>path</code></td><td>路由路径；已有页面迁移后保留绝对深链</td></tr><tr><td><code>component</code></td><td>如 <code>system/news/index</code>，对应 views 下文件，不带 <code>.vue</code></td></tr><tr><td><code>perms</code></td><td>服务端检查的精确权限串，如 <code>system:news:list</code></td></tr><tr><td><code>visible</code> / <code>status</code></td><td>控制显示和启停；不替代服务端权限检查</td></tr><tr><td><code>isFrame</code> / <code>isCache</code></td><td>按当前管理页面枚举提交，不自行解释为布尔字段</td></tr></tbody></table><h2 id="操作步骤" tabindex="-1">操作步骤 <a class="header-anchor" href="#操作步骤" aria-label="Permalink to &quot;操作步骤&quot;">​</a></h2><p>具有相应 <code>system:menu:*</code> 权限的用户先读取菜单树，选择父级，填写路由、组件与权限串后保存。随后在角色管理分配页面和按钮权限，用目标身份重新登录，检查菜单、深链刷新及直接 API 请求。</p><p>创建一个新的业务页面应放入现有合适目录。不要为文档、个人通知或已删除示例业务再建立第四个一级菜单。当前个人通知由受保护的核心路由与菜单组合逻辑提供；运行表单和记录页是隐藏路由，不能当作普通公开菜单发放。</p><h2 id="正常结果与恢复" tabindex="-1">正常结果与恢复 <a class="header-anchor" href="#正常结果与恢复" aria-label="Permalink to &quot;正常结果与恢复&quot;">​</a></h2><p>正确组件路径能够加载真实页面；未授权页面被拒绝或不出现在菜单中。组件未找到会进入路由错误恢复界面，应检查路径与文件大小写，不能用空白页掩盖。更改父级后旧链接应继续按绝对 path 工作；树出现重复入口时先核对现有菜单和核心路由，避免重复插入。</p><p>最新菜单迁移保留现存页面/按钮授权；旧资料、网站、下载与页面业务模块已移除。微信旧配置深链转向业务配置的微信分区，具体行为见<a href="/xinghui-admin-vue3/docs/features/business-config.html">业务配置</a>。</p><h2 id="源码依据" tabindex="-1">源码依据 <a class="header-anchor" href="#源码依据" aria-label="Permalink to &quot;源码依据&quot;">​</a></h2><ul><li>前端：<code>apps/web-ele/src/api/system/menu.ts</code>、<code>apps/web-ele/src/views/system/menu/index.vue</code>。</li><li>路由加载：<code>apps/web-ele/src/router/routes-helper.ts</code>；核心入口：<code>apps/web-ele/src/router/routes/core.ts</code>。</li><li>后端：<code>system-admin/src/main/java/com/xinghuiTec/controller/SysMenuController.java</code>。</li><li>旧三组层级：<code>system-admin/src/main/resources/db/migration/V20261013_170__menu_consolidation.sql</code>；当前独立AI组与动作：<code>V20261016_180__ai_config_v04.sql</code>、<code>V20261016_210__ai_access_actions.sql</code>（同目录）。</li></ul>',12)])])}const p=t(r,[["render",c]]);export{h as __pageData,p as default};
